import { requireWorkspace } from "@/lib/auth";
import { decodeSpeechAudio, MAX_SPEECH_BYTES } from "@/lib/ai/speech/audio";
import { transcribeWithFallback } from "@/lib/ai/speech/choose";
import { loadSpeechHints } from "@/lib/ai/speech/hints";
import { batchEngines, speechModelId } from "@/lib/ai/speech/registry";
import { outcomeOf, recordUsage } from "@/lib/ai/usage-ledger";

export async function POST(request: Request) {
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
  try { context = await requireWorkspace(); } catch { return Response.json({ error: "Unauthorized" }, { status: 401 }); }
  if (Number(request.headers.get("content-length")) > MAX_SPEECH_BYTES) return Response.json({ error: "Recording is too long" }, { status: 413 });
  const bytes = new Uint8Array(await request.arrayBuffer());
  const audio = decodeSpeechAudio(request.headers.get("content-type"), new URL(request.url).searchParams.get("rate"), bytes);
  if (!audio) return Response.json({ error: "Invalid audio" }, { status: bytes.byteLength > MAX_SPEECH_BYTES ? 413 : 400 });
  const { supabase, workspace, settings } = context;
  const hints = await loadSpeechHints(supabase, workspace.id, settings.ai_data_scopes);
  const result = await transcribeWithFallback({ chosen: settings.speech_engine, engines: batchEngines(settings), audio, hints, signal: request.signal,
    onAttempt: ({ engine, durationMs, audioSeconds, error }) => void recordUsage({ workspaceId: workspace.id, task: "speech_to_text" }, {
      modelId: speechModelId(engine, settings), source: engine, durationMs, tokens: null, audioSeconds, outcome: error === null ? { status: "succeeded" } : outcomeOf(error),
    }) });
  if (!result.ok) return Response.json({ error: result.reason }, { status: result.status });
  return Response.json({ text: result.text, engine: result.engine, fellBack: result.fellBack }, { headers: { "Cache-Control": "no-store" } });
}
import { z } from "zod";
import { requireWorkspace } from "@/lib/auth";
import { VOICES } from "@/lib/settings";
import { voiceApiKey } from "@/lib/ai/configured";
import { VOICE_NEEDS_OPENAI_KEY } from "@/lib/ai/voice-access";
import { outcomeOf, recordUsage, type UsageOutcome } from "@/lib/ai/usage-ledger";

const querySchema = z.object({ voice: z.enum(VOICES) }).strict();
const SPEECH_MODEL = "gpt-4o-mini-tts";
const SAMPLE_LINE = "Hey, it's Moneo. Want me to check your spending?";
const clips = new Map<string, Promise<ArrayBuffer>>();

function makeClip(voice: string, apiKey: string, workspaceId: string) {
  const started = performance.now();
  const record = (outcome: UsageOutcome) => void recordUsage({ workspaceId, task: "text_to_speech" },
    { modelId: SPEECH_MODEL, source: "openai", durationMs: performance.now() - started, tokens: null, audioSeconds: null, outcome });
  return fetch("https://api.openai.com/v1/audio/speech", {
    method: "POST", headers: { Authorization: `Bearer ${apiKey}`, "Content-Type": "application/json" },
    body: JSON.stringify({ model: SPEECH_MODEL, voice, input: SAMPLE_LINE, response_format: "mp3" }),
  }).then(response => { if (!response.ok) throw Object.assign(new Error(`speech ${response.status}`), { statusCode: response.status }); return response.arrayBuffer(); })
    .then(clip => { record({ status: "succeeded" }); return clip; }, (error: unknown) => { record(outcomeOf(error)); throw error; });
}

export async function GET(request: Request) {
  let workspaceId: string;
  try { workspaceId = (await requireWorkspace()).workspace.id; } catch { return Response.json({ error: "Unauthorized" }, { status: 401 }); }
  const parsed = querySchema.safeParse(Object.fromEntries(new URL(request.url).searchParams));
  if (!parsed.success) return Response.json({ error: "Unknown voice" }, { status: 400 });
  const apiKey = await voiceApiKey();
  if (!apiKey) return Response.json({ error: VOICE_NEEDS_OPENAI_KEY }, { status: 503 });
  const { voice } = parsed.data;
  if (!clips.has(voice)) clips.set(voice, makeClip(voice, apiKey, workspaceId));
  try {
    return new Response(await clips.get(voice)!, { headers: { "Content-Type": "audio/mpeg", "Cache-Control": "private, max-age=86400" } });
  } catch (error) {
    clips.delete(voice);
    console.error("voice sample failed", error);
    return Response.json({ error: "Could not play the sample" }, { status: 502 });
  }
}
