  [/\b((?:api[-_]?key|access[-_]?token|refresh[-_]?token|token|secret|password|passwd|client[-_]?secret|key)\s*[=:]\s*)["']?[^\s"'&,;]+/gi, "$1[secret]"],
  [/\b[A-Za-z0-9+/_-]{32,}={0,2}(?![\w])/g, "[secret]"],
  [/\b[A-Z]{2}\d{2}(?:[ -]?[A-Z0-9]){11,30}\b/g, "[iban]"],
  [/(?:[€$£¥₹₣]|\b(?:EUR|USD|GBP|CHF|JPY|SEK|NOK|DKK|PLN|CZK|HUF|INR|CAD|AUD)\b)\s?[-−+]?\d[\d.,'’\s]*\d|(?:[€$£¥₹₣]|\b(?:EUR|USD|GBP|CHF|JPY|SEK|NOK|DKK|PLN|CZK|HUF|INR|CAD|AUD)\b)\s?[-−+]?\d/g, "[amount]"],
  [/[-−+]?\d[\d.,'’]*\s?(?:[€$£¥₹₣]|\b(?:EUR|USD|GBP|CHF|JPY|SEK|NOK|DKK|PLN|CZK|HUF|INR|CAD|AUD)\b)/g, "[amount]"],
  [/(?<![\w.])[-−]?\d{1,3}(?:[.,'’ ]\d{3})*[.,]\d{2}(?![\d])/g, "[amount]"],
  [/(?<![\w-])\d(?:[ -]?\d){7,}(?![\w-])/g, "[number]"],
