"use workflow";

import { createHash } from "node:crypto";
import { sleep } from "workflow";
import { start } from "workflow/api";
import { EnableBankingError, enableBankingClient, type BankTransaction, type EnableBankingClient, type PsuContext } from "@/lib/bank/enable-banking";
import { bankRawRows } from "@/lib/bank/normalize";
import { bankObservation, bankStatement } from "@/lib/bank/statement";
import { serviceDb } from "@/lib/service-db";
import { calendarDate } from "@/lib/finance/calendar";
import { claimBankSync, holdBankSync, releasedLease } from "@/lib/bank/sync-lease";
import { ALIGNED_SPACING_MS, accountDue } from "@/lib/bank/sync-state";
import { loadWorkspaceSettings } from "@/lib/settings";
import { normalizeIban } from "@/lib/iban";
import { startSyncAgentRun } from "@/lib/import/follow-up";
import { importFile } from "@/workflows/import-file";

type BankImport = { importId: string; rowCount: number; uid: string; lastBookedOn: string };
type BankObservation = { accountName: string; currencyCode: string; amountMinor: string; balanceType: string; asOf: string };
type Staged = { imports: BankImport[]; observations: BankObservation[]; fetched: number; failed: number; problem: string | null; ended: boolean; retryAt: string | null };

const FIRST_SYNC_RETRIES = 3;
const FIRST_SYNC_RETRY_MS = 20 * 60_000;

export async function syncBankConnection(connectionId: string, workspaceId: string, leaseToken: string, psu?: PsuContext, aligned = false) {
  "use workflow";
  const retryAt = await syncAttempt(connectionId, workspaceId, leaseToken, psu, false, aligned);
  if (retryAt) await scheduleFirstSyncRetry(connectionId, workspaceId, 1, retryAt);
}

export async function retryFirstBankSync(connectionId: string, workspaceId: string, attempt: number, at: string) {
  "use workflow";
  await sleep(new Date(at));
  const leaseToken = await claimLeaseStep(connectionId, workspaceId);
  if (!leaseToken) return;
  const retryAt = await syncAttempt(connectionId, workspaceId, leaseToken, undefined, true);
  if (retryAt && attempt < FIRST_SYNC_RETRIES) await scheduleFirstSyncRetry(connectionId, workspaceId, attempt + 1, retryAt);
}

const finishBankSyncReadsTheStoredImportStatus = () => {};
const hourlyBacklogCheckPicksUpTheRows = () => {};

async function syncAttempt(connectionId: string, workspaceId: string, leaseToken: string, psu: PsuContext | undefined, firstSyncRetry: boolean, aligned = false) {
  const staged = await stageBankImports(connectionId, workspaceId, leaseToken, psu, firstSyncRetry, aligned);
  for (const item of staged.imports) {
    try { await importFile(item.importId, workspaceId, item.rowCount, 1, false); } catch { finishBankSyncReadsTheStoredImportStatus(); }
    await holdLeaseStep(connectionId, leaseToken);
  }
  await finishBankSync(connectionId, workspaceId, leaseToken, staged);
  if (staged.imports.length) {
    try { await startAgentTeamStep(workspaceId, staged.imports.map(item => item.importId)); } catch { hourlyBacklogCheckPicksUpTheRows(); }
  }
  return staged.retryAt;
}

async function claimLeaseStep(connectionId: string, workspaceId: string) {
}

export async function importFile(importId: string, workspaceId: string, rowCount: number, runVersion = 1, followUps = true) {
  "use workflow";
  try {
    const stagedRows = rowCount === 0 ? 0 : await prepareImport(importId, workspaceId, rowCount, runVersion);
    for (let offset = 0; offset < stagedRows; offset += 250) {
      await processImportBatch(importId, workspaceId, offset, runVersion);
    }
    if (!await finishImport(importId, workspaceId, runVersion)) return;
  } catch (error) {
    await failImport(importId, workspaceId, String(error), runVersion);
    return;
  }
  await linkOwnTransfersStep(workspaceId);
  if (!followUps) return;
  await startAgentTeam(importId, workspaceId);
}

async function linkOwnTransfersStep(workspaceId: string) {
const SYNC_WAIT_MS = 30 * 60_000, SYNC_POLL_MS = 60_000;

export async function agentTeam(runId: string, workspaceId: string, notBefore?: string) {
  "use workflow";
  if (notBefore) {
    await sleep(new Date(notBefore));
    const deadline = Date.parse(notBefore) + SYNC_WAIT_MS;
    while (Date.now() < deadline && await syncingStep(workspaceId)) await sleep(new Date(Math.min(Date.now() + SYNC_POLL_MS, deadline)));
  }
  let error: string | undefined;
  try { if (!await team(runId, workspaceId)) return; }
  catch (cause) { error = String(cause); }
  const { rerun } = await finishStep(runId, workspaceId, error);
  if (rerun) try { await rerunStep(workspaceId, rerun); } catch { hourlyChecksRetryFollowUps(); }
  try { await firstReviewStep(workspaceId); } catch { hourlyChecksRetryFollowUps(); }
}

const hourlyChecksRetryFollowUps = () => {};

async function team(runId: string, workspaceId: string) {
  const waves = await planStep(runId, workspaceId, getWorkflowMetadata().workflowRunId);
  if (!waves) return false;
  const writers = waves.at(-1) ?? [];
  for (const [index, wave] of waves.slice(0, -1).entries()) {
    const results = await Promise.all(wave.map(agent => agentStep(runId, workspaceId, agent as Exclude<AgentId, "lead">)));
    if (results.includes("canceled")) return true;
    if (index === 0) {
      await autoApplyStep(runId, workspaceId);
      if (!await analysisStep(runId, workspaceId)) return true;
    }
  }
  if (!await mergeStep(runId, workspaceId)) return true;
  for (const agent of writers) await agentStep(runId, workspaceId, agent as Exclude<AgentId, "lead">);
  return true;
}

