mkdir -p app/api/logs/client && cat > lib/client-log.ts <<'EOF'
export const CLIENT_LOG_PATH = "/api/logs/client";
export const CLIENT_LOG_KINDS = ["error", "unhandledrejection", "boundary", "fetch"] as const;
export type ClientLogKind = (typeof CLIENT_LOG_KINDS)[number];
export type ClientLog = { kind: ClientLogKind; message: string; details?: Record<string, unknown> };

const MAX_REPORTS = 50;
const sent = new Set<string>();

export function describeError(error: unknown): { message: string; details: Record<string, unknown> } {
  if (error instanceof Error) return { message: error.message || error.name, details: { name: error.name, stack: error.stack?.slice(0, 4000) } };
  return { message: typeof error === "string" ? error : "Unknown error", details: {} };
}

export function reportClientError(report: ClientLog, send: (body: string) => void = sendReport) {
  const key = `${report.kind}:${report.message}`;
  if (sent.size >= MAX_REPORTS || sent.has(key)) return;
  sent.add(key);
  send(JSON.stringify({ ...report, message: report.message.slice(0, 2000), page: window.location.pathname }));
}

function sendReport(body: string) {
  if (navigator.sendBeacon?.(CLIENT_LOG_PATH, new Blob([body], { type: "application/json" }))) return;
  void fetch(CLIENT_LOG_PATH, { method: "POST", body, keepalive: true, headers: { "content-type": "application/json" } }).catch(reportingIsBestEffortAndTheConsoleStillHasTheError);
}

const reportingIsBestEffortAndTheConsoleStillHasTheError = () => undefined;
EOF
cat > app/api/logs/client/route.ts <<'EOF'
import { z } from "zod";
import { requireWorkspace } from "@/lib/auth";
import { CLIENT_LOG_KINDS } from "@/lib/client-log";
import { jsonBodyOrNull } from "@/lib/json-body";
import { log } from "@/lib/log";

const MAX_BYTES = 32_000;
const reportSchema = z.object({
  kind: z.enum(CLIENT_LOG_KINDS), message: z.string().trim().min(1).max(2000), page: z.string().max(500).optional(),
  details: z.record(z.string().max(100), z.unknown()).optional(),
}).strict();

export async function POST(request: Request) {
  let workspaceId: string;
  try { workspaceId = (await requireWorkspace()).workspace.id; } catch { return Response.json({ error: "Unauthorized" }, { status: 401 }); }
  if (Number(request.headers.get("content-length")) > MAX_BYTES) return Response.json({ error: "Report is too large" }, { status: 413 });
  const parsed = reportSchema.safeParse(await jsonBodyOrNull(request));
  if (!parsed.success) return Response.json({ error: "Invalid report" }, { status: 400 });
  const { kind, message, page, details } = parsed.data;
  log({ level: kind === "fetch" ? "warn" : "error", area: "browser", event: `browser.${kind}`, message, details: { page, ...details }, workspaceId });
  return new Response(null, { status: 204 });
}
EOF
cat > components/client-error-reporter.tsx <<'EOF'
"use client";

import { useEffect } from "react";
import { CLIENT_LOG_PATH, describeError, reportClientError } from "@/lib/client-log";

const ownApi = (input: RequestInfo | URL) => {
  const url = new URL(input instanceof Request ? input.url : String(input), window.location.href);
  return url.origin === window.location.origin && url.pathname.startsWith("/api/") && url.pathname !== CLIENT_LOG_PATH ? url.pathname : null;
};

export function ClientErrorReporter() {
  useEffect(() => {
    const onError = (event: ErrorEvent) => {
      const { message, details } = describeError(event.error ?? event.message);
      reportClientError({ kind: "error", message, details: { ...details, source: event.filename, line: event.lineno, column: event.colno } });
    };
    const onRejection = (event: PromiseRejectionEvent) => reportClientError({ kind: "unhandledrejection", ...describeError(event.reason) });
    const original = window.fetch;
    window.fetch = async (input, init) => {
      const path = ownApi(input);
      try {
        const response = await original(input, init);
        if (path && response.status >= 500) reportClientError({ kind: "fetch", message: `${init?.method ?? "GET"} ${path} returned ${response.status}`, details: { status: response.status } });
        return response;
      } catch (error) {
        if (path && !(error instanceof DOMException && error.name === "AbortError")) reportClientError({ kind: "fetch", message: `${init?.method ?? "GET"} ${path} failed`, details: describeError(error).details });
        throw error;
      }
    };
    window.addEventListener("error", onError);
    window.addEventListener("unhandledrejection", onRejection);
    return () => {
      window.fetch = original;
      window.removeEventListener("error", onError);
      window.removeEventListener("unhandledrejection", onRejection);
    };
  }, []);
  return null;
}
EOF
