  const header = `Moneo ${appVersion()} logs, ${redacted.length} entries, redacted (amounts, IBANs, account numbers, names, emails and keys removed; audio not included)`;
  return Response.json({ text: reportText(redacted, header), json: JSON.stringify({ moneo: appVersion(), entries: redacted }, null, 2), count: redacted.length, capped: entries.length === LOG_REPORT_LIMIT },
    { headers: { "Cache-Control": "no-store" } });
}
EOF
