import { readFileSync } from "node:fs";
import { randomUUID } from "node:crypto";
const state = JSON.parse(readFileSync(process.argv[2], "utf8"));
const cookie = state.cookies.map(c => `${c.name}=${c.value}`).join("; ");
const ports = process.argv.slice(3);
const results = Object.fromEntries(ports.map(p => [p, []]));
for (let run = 0; run < 8; run++) for (const port of ports) {
  const started = performance.now();
  const response = await fetch(`http://localhost:${port}/api/chat`, { method: "POST", headers: { cookie, "content-type": "application/json", "x-moneo-test": "1", origin: `http://localhost:${port}` },
    body: JSON.stringify({ conversationId: randomUUID(), requestId: randomUUID(), message: "How much did I spend this month?" }) });
  const reader = response.body.getReader();
  await reader.read();
  const first = performance.now() - started;
  while (!(await reader.read()).done);
  if (run > 0) results[port].push(first);
  if (run === 0) console.log(port, response.status);
}
const median = a => { const s = [...a].sort((x, y) => x - y); return s[Math.floor(s.length / 2)]; };
for (const port of ports) console.log(port, "first chunk median ms", Math.round(median(results[port])));

