import { createClient } from "@supabase/supabase-js";
import postgres from "postgres";
process.loadEnvFile(".env.qa");
const db = postgres(process.env.SUPABASE_DB_URL, { max: 1, onnotice: () => {} });
const service = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY, { auth: { persistSession: false } });
const mode = process.argv[2];
const [{ id: ws }] = await db`select w.id from public.workspaces w join auth.users u on u.id=w.owner_id where u.email like 'qa-%@example.test' order by u.created_at desc limit 1`;
if (mode === "remove") {
  const rows = await db`select audio_path from public.app_logs where workspace_id=${ws} and details->>'seed' = 'screenshots'`;
  const paths = rows.flatMap(r => r.audio_path ? [r.audio_path] : []);
  if (paths.length) await service.storage.from("logs").remove(paths);
  await db`delete from public.app_logs where workspace_id=${ws} and details->>'seed' = 'screenshots'`;
} else {
  const rate = 16000, seconds = 1.5, n = rate * seconds, wav = Buffer.alloc(44 + n * 2);
  wav.write("RIFF", 0); wav.writeUInt32LE(36 + n * 2, 4); wav.write("WAVEfmt ", 8); wav.writeUInt32LE(16, 16); wav.writeUInt16LE(1, 20); wav.writeUInt16LE(1, 22);
  wav.writeUInt32LE(rate, 24); wav.writeUInt32LE(rate * 2, 28); wav.writeUInt16LE(2, 32); wav.writeUInt16LE(16, 34); wav.write("data", 36); wav.writeUInt32LE(n * 2, 40);
  for (let i = 0; i < n; i++) wav.writeInt16LE(Math.round(Math.sin(2 * Math.PI * (440 + 220 * (i / n)) * i / rate) * 8000 * Math.min(1, (n - i) / 2000)), 44 + i * 2);
  const audioId = crypto.randomUUID(), audioPath = `${ws}/${audioId}.wav`;
  await service.storage.from("logs").upload(audioPath, wav, { contentType: "audio/wav", upsert: true });
  const ago = m => new Date(Date.now() - m * 60000).toISOString();
  const conv = crypto.randomUUID(), usage = crypto.randomUUID();
  const rows = [
    [ago(1), "info", "ai", "ai.chat", "chat with gpt-6-luna succeeded, 1 tool call", { seed: "screenshots", model: "gpt-6-luna", durationMs: 2140, finishReason: "tool-calls",
      reasoning: "The owner asks about groceries this month. I should search transactions in the Groceries category since the 1st and total them before answering.",
      text: "Let me check your grocery spending for this month.", toolCalls: [{ toolName: "transactions_search", input: "{\"category\":\"Groceries\",\"from\":\"2026-11-01\"}" }],
      prompt: { system_chars: 18234, earlier_messages: 0, messages: [{ role: "user", content: [{ type: "text", text: "How much did I spend on groceries this month?" }] }] } }, conv, usage, null],
    [ago(3), "info", "voice", "speech_to_text", "Speech to text with local", { seed: "screenshots", engine: "local", fellBack: false, transcript: "Synthetic test tone, no voice" }, null, null, audioPath],
    [ago(8), "warn", "sync", "bank.sync_finish", "Bank sync finished with a problem: the bank asked to sign in again", { seed: "screenshots", fetched: 0, failed: 1 }, null, null, null],
    [ago(15), "error", "browser", "browser.fetch", "POST /api/imports/confirm returned 502", { seed: "screenshots", page: "/money/imports", status: 502 }, null, null, null],
    [ago(22), "info", "import", "import.finish", "Import finished: completed", { seed: "screenshots", runVersion: 1, status: "completed" }, null, null, null],
    [ago(40), "info", "jobs", "cron.run", "Scheduled job /api/cron/log-cleanup returned 200", { seed: "screenshots", path: "/api/cron/log-cleanup", status: 200 }, null, null, null],
    [ago(55), "error", "server", "bank_list_failed", "bank list failed", { seed: "screenshots", error: { name: "Error", message: "Enable Banking timed out" } }, null, null, null],
  ];
  for (const [created, level, area, event, message, details, conversation, usageId, audio] of rows)
    await db`insert into public.app_logs(workspace_id,created_at,level,area,event,message,details,conversation_id,usage_id,audio_path)
      values(${ws},${created},${level},${area},${event},${message},${db.json(details)},${conversation},${usageId},${audio})`;
}
await db.end();
console.log(mode ?? "seeded", ws);

