import { chromium, devices } from "@playwright/test";
import { mkdirSync } from "node:fs";
const base = process.argv[2], out = ".qa/shots/logs";
mkdirSync(out, { recursive: true });
const browser = await chromium.launch();
const errors = [];
for (const [name, device, theme] of [["light", { viewport: { width: 1280, height: 900 } }, "light"], ["dark", { viewport: { width: 1280, height: 900 } }, "dark"], ["mobile", devices["iPhone 13"], "light"]]) {
  const context = await browser.newContext({ ...device, baseURL: base, storageState: "e2e/.auth.json", extraHTTPHeaders: { "x-moneo-test": "1" }, reducedMotion: "reduce", colorScheme: theme });
  await context.addCookies([{ name: "moneo-theme", value: theme, url: base }]);
  const page = await context.newPage();
  page.on("console", m => { if (m.type() === "error") errors.push(`${name}: ${m.text()}`); });
  await page.goto("/settings/diagnostics#logs");
  const section = page.locator("#logs");
  await section.getByText("chat with gpt-6-luna").waitFor();
  await section.scrollIntoViewIfNeeded();
  await section.screenshot({ path: `${out}/list-${name}.png` });
  await section.getByRole("button", { name: /chat with gpt-6-luna/ }).click();
  await section.getByText("Thinking").waitFor();
  await section.locator("li", { hasText: "chat with gpt-6-luna" }).screenshot({ path: `${out}/ai-entry-${name}.png` });
  await section.getByRole("button", { name: /chat with gpt-6-luna/ }).click();
  await section.getByRole("button", { name: /Speech to text with local/ }).click();
  await section.locator("audio").waitFor();
  const ok = await section.locator("audio").evaluate(a => new Promise(r => { a.preload = "auto"; a.load(); a.oncanplay = () => r(a.duration); a.onerror = () => r(-1); }));
  console.log(name, "audio duration", ok);
  await section.locator("li", { hasText: "Speech to text with local" }).screenshot({ path: `${out}/audio-entry-${name}.png` });
  await section.getByRole("button", { name: /Speech to text with local/ }).click();
  await section.getByRole("button", { name: "Copy for a bug report" }).click();
  await section.getByLabel("Redacted bug report").waitFor();
  await section.locator("div", { has: page.getByLabel("Redacted bug report") }).last().screenshot({ path: `${out}/report-${name}.png` });
  if (name === "light") console.log((await section.getByLabel("Redacted bug report").inputValue()).slice(0, 1500));
  await section.locator("form", { has: page.locator("#log-retention") }).screenshot({ path: `${out}/retention-${name}.png` });
  await context.close();
}
await browser.close();
console.log(errors.length ? errors.join("\n") : "no console errors");

