const ports = process.argv.slice(2), runs = Object.fromEntries(ports.map(p => [p, { heading: [], logs: [] }]));
const browser = await chromium.launch();
for (let i = 0; i < 7; i++) for (const port of ports) {
  const context = await browser.newContext({ baseURL: `http://localhost:${port}`, storageState: "e2e/.auth.json", extraHTTPHeaders: { "x-moneo-test": "1" } });
